<?php defined('BASEPATH') or exit('No direct script access allowed'); ?>
<div class="card">
    <div class="card-header d-flex justify-content-between align-items-center"><div><h4 class="header-title mb-0">Pengumuman Dompet</h4><small class="text-muted">Publikasi web/data saja; push notification tidak diasumsikan tersedia.</small></div><button id="add" class="btn btn-sm btn-primary"><i class="ri-add-line me-1"></i>Tambah</button></div>
    <div class="card-body">
        <div class="row g-2 mb-3"><div class="col-md-5"><input id="search" class="form-control" placeholder="Cari judul atau isi"></div><div class="col-md-3"><select id="announcementStatusFilter" class="form-select"><option value="">Semua status</option><option>AKTIF</option><option>NONAKTIF</option></select></div><div class="col-md-2"><button id="filter" class="btn btn-outline-primary w-100">Terapkan</button></div></div>
        <div id="rows" class="sdk-record-list"><div class="sdk-record-empty">Memuat data...</div></div>
        <div class="sdk-pager-wrap"><div><small id="info" class="text-muted"></small><div class="mt-2" id="announcementPagination"></div></div><div class="sdk-page-size"><label for="announcementPageSize" class="mb-0">Tampilkan</label><select class="form-select form-select-sm" id="announcementPageSize"><option value="10" selected>10</option><option value="25">25</option><option value="50">50</option><option value="100">100</option></select><span>entri</span></div></div>
    </div>
</div>
<div class="modal fade" id="modal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Pengumuman</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><form id="form"><input type="hidden" name="id"><input type="hidden" name="web_csrf_token" value="<?=html_escape($csrf_token)?>"><label class="form-label">Judul</label><input name="judul" class="form-control"><label class="form-label mt-2">Isi Pengumuman</label><textarea name="isi" class="form-control" rows="6"></textarea><div class="row"><div class="col-md-4"><label class="form-label mt-2">Target</label><select name="target_pengguna" class="form-select"><option>SEMUA</option><option>WALI</option><option>SISWA</option></select></div><div class="col-md-4"><label class="form-label mt-2">Mulai</label><input name="tanggal_mulai" type="date" class="form-control"></div><div class="col-md-4"><label class="form-label mt-2">Selesai</label><input name="tanggal_selesai" type="date" class="form-control"></div></div></form></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Tutup</button><button id="save" class="btn btn-primary">Simpan</button></div></div></div></div>
<script>
$(function(){
    const base=<?=json_encode(base_url('admin/dompet/pengumuman/'),JSON_UNESCAPED_SLASHES)?>,csrf=<?=json_encode($csrf_token)?>,modal=new bootstrap.Modal(document.getElementById('modal'));
    const escapeHtml=value=>$('<div>').text(value==null||value===''?'-':value).html(),request=(url,data)=>$.post(base+url,data,null,'json'),fail=xhr=>Swal.fire('Gagal',(xhr.responseJSON||{}).message||'Terjadi kesalahan.','error');
    const plainText=value=>{const parsed=new DOMParser().parseFromString(String(value??''),'text/html');return (parsed.body.textContent||'').replace(/\u00a0/g,' ').replace(/[ \t]+/g,' ').replace(/\n\s*\n+/g,'\n').trim();};
    let page=1,limit=10;
    function load(rebuildPager){request('result',{search:$('#search').val(),status:$('#announcementStatusFilter').val(),page:page,limit:limit}).done(response=>{let html='';(response.data||[]).forEach((row,index)=>{const announcement=plainText(row.isi),preview=announcement.slice(0,180);html+=`<div class="sdk-record-card"><div class="sdk-record-head"><span>Target: <strong>${escapeHtml(row.target_pengguna)}</strong></span>${SDKreatifUI.statusBadge(row.status_aktif)}</div><div class="sdk-record-main"><div class="flex-grow-1"><h5 class="sdk-record-title">${(page-1)*limit+index+1}. ${escapeHtml(row.judul)}</h5><p class="mb-2 text-muted" style="white-space:pre-line">${escapeHtml(preview)}${announcement.length>180?'…':''}</p><div class="sdk-record-meta"><span><i class="ri-calendar-line me-1"></i>Mulai: <strong>${escapeHtml(row.tanggal_mulai)}</strong></span><span>Selesai: <strong>${escapeHtml(row.tanggal_selesai)}</strong></span></div></div><div class="sdk-record-actions"><button class="btn btn-sm btn-outline-primary edit" data-id="${row.id}" title="Edit" aria-label="Edit" data-bs-toggle="tooltip"><i class="ri-edit-line"></i></button><button class="btn btn-sm btn-outline-secondary toggle" data-id="${row.id}" data-status="${row.status_aktif==='AKTIF'?'NONAKTIF':'AKTIF'}" title="Ubah status" aria-label="Ubah status" data-bs-toggle="tooltip"><i class="ri-toggle-line"></i></button></div></div></div>`;});$('#rows').html(html||'<div class="sdk-record-empty">Tidak ada data.</div>');SDKreatifUI.refreshTooltips('#rows');page=response.meta.page;$('#info').text(response.meta.total+' pengumuman');if(rebuildPager!==false)SDKreatifUI.serverPager('#announcementPagination',response.meta,paging=>{page=paging.currentPage;load(false);});}).fail(fail);}
    $('#add').on('click',()=>{$('#form')[0].reset();$('#form [name="id"]').val('');modal.show();});$('#filter').on('click',()=>{page=1;load(true);});$('#announcementPageSize').on('change',function(){limit=parseInt(this.value,10)||10;page=1;load(true);});$('#search').on('keydown',event=>{if(event.key==='Enter'){page=1;load(true);}});
    $('#save').on('click',()=>request('simpan',$('#form').serialize()).done(response=>{modal.hide();load(true);Swal.fire('Berhasil',response.message,'success');}).fail(fail));
    $('#rows').on('click','.edit',function(){request('detail',{id:$(this).data('id')}).done(response=>{Object.keys(response.data).forEach(key=>$('#form [name="'+key+'"]').val(key==='isi'?plainText(response.data[key]):response.data[key]));modal.show();}).fail(fail);});
    $('#rows').on('click','.toggle',function(){request('status',{id:$(this).data('id'),status:$(this).data('status'),web_csrf_token:csrf}).done(()=>load(true)).fail(fail);});
    load(true);
});
</script>
